const API_URL='https://enformafit-backend-production.up.railway.app';
let API_TOKEN=localStorage.getItem('ef_token')||null;
let API_ROLE=localStorage.getItem('ef_role')||null;

function fmtFecha(f){
  if(!f)return'—';
  if(f.includes('/'))return f; // already formatted
  const p=f.split('-');
  if(p.length===3)return p[2]+'/'+p[1]+'/'+p[0];
  return f;
}
function fmtFechaCorta(f){
  if(!f)return'—';
  const p=f.split('-');
  if(p.length===3)return p[2]+'/'+p[1];
  return f;
}
async function apiCall(method,path,body){
  const opts={method,headers:{'Content-Type':'application/json'}};
  if(API_TOKEN)opts.headers['Authorization']='Bearer '+API_TOKEN;
  if(body)opts.body=JSON.stringify(body);
  console.log('[API]',method,path);
  try{
    const r=await fetch(API_URL+path,opts);
    const data=await r.json();
    if(!r.ok){
      console.error('[API] Error',r.status,path,data);
      if(r.status===401||r.status===403){
        API_TOKEN=null;localStorage.removeItem('ef_token');
        showLogin();
      }
      throw new Error(data.error||'Error '+r.status);
    }
    return data;
  }catch(e){
    console.error('[API] Fetch error',path,e.message);
    throw e;
  }
}

