async function doLogin(){
  const email=document.getElementById('login-email')?.value;
  const pass=document.getElementById('login-pass')?.value;
  const errEl=document.getElementById('login-err');
  if(!email||!pass){if(errEl)errEl.textContent='Rellena todos los campos';return;}
  try{
    if(errEl)errEl.textContent='Entrando...';
    const data=await apiCall('POST','/api/auth/login',{email,password:pass});
    API_TOKEN=data.token;API_ROLE=data.role;
    localStorage.setItem('ef_token',API_TOKEN);
    localStorage.setItem('ef_role',API_ROLE);
    // Detectar entrenador por email
    const emailLow=email.toLowerCase();
    if(emailLow==='gerardsalac20@gmail.com'){
      window.ENTRENADOR_ACTIVO='gerard';
      toast('✅ Bienvenido Gerard','vd');
      const tb=document.getElementById('tb-trainer');if(tb)tb.textContent='👤 Gerard Sala';
    } else {
      window.ENTRENADOR_ACTIVO='alvaro';
      toast('✅ Bienvenido Álvaro','vd');
      const tb=document.getElementById('tb-trainer');if(tb)tb.textContent='👤 Álvaro Casal';
    }
    await loadClientesFromAPI();
    nav('ci');
  }catch(e){
    if(errEl)errEl.textContent=e.message||'Error de acceso';
  }
}

async function loadClientesFromAPI(){
  console.log('[API] Cargando clientes desde BD...');
  try{
    const rows=await apiCall('GET','/api/clientes');
    console.log('[API] Respuesta BD:',rows?.length,'clientes');
    if(!rows||!rows.length)return;

    const mapped=rows.map(r=>{
      const nom=r.nombre||'';
      const partes=nom.trim().split(' ');
      const init=((partes[0]?.[0]||'')+(partes[1]?.[0]||'')).toUpperCase()||'CL';
      const toDate=d=>d?new Date(d).toISOString().split('T')[0]:'';
      
      // Semanas revision
      const semRev=Array.isArray(r.semanas_revision)?r.semanas_revision:[4,8,12];
      const semana=parseInt(r.semana_actual)||0;
      const nextRev=semRev.find(s=>s>=semana)||semRev[semRev.length-1];
      
      // Pesos from historial
      const pesoAct=parseFloat(r.peso_actual||r.peso_inicial)||80;
      const pesoIni=parseFloat(r.peso_inicial)||80;
      
      // Macros — from planes_nutricion if available, else kcal_asignadas
      const kcal=parseInt(r.kcal_total||r.kcal_asignadas)||2000;
      const prot=parseInt(r.proteina_g)||160;
      const carbs=parseInt(r.carbos_g)||200;
      const grasa=parseInt(r.grasas_g)||60;
      
      // Rutina dias and objetivo_kg from notas_entrenador JSON
      let rutinaDias={}, rutinaSemanas={}, objetivoKg=null, semanaActual=semana, entrenadorAsignado='alvaro';
      try{
        if(r.notas_entrenador){
          const notas=JSON.parse(r.notas_entrenador);
          rutinaDias=notas.rutina_base||notas.rutina_dias||{};
          rutinaSemanas=notas.rutina_semanas||{};
          objetivoKg=notas.objetivo_kg||null;
          semanaActual=notas.semana_actual||semana;
          entrenadorAsignado=notas.entrenador||'alvaro';
        }
      }catch(e){}
      
      // Parse notas cliente JSON — extract all formulario fields
      let notasCliente={}, comentarioReal='', medidasS0=null;
      try{
        if(r.notas){
          const nc=JSON.parse(r.notas);
          notasCliente=nc;
          comentarioReal=nc.comentarios||'';
          medidasS0=nc.medidas_s0||null;
        }
      }catch(e){ comentarioReal=r.notas||''; }
      
      // Alimentos from distribucion
      let alimentos={};
      try{if(r.distribucion)alimentos=typeof r.distribucion==='string'?JSON.parse(r.distribucion):r.distribucion;}catch(e){}
      
      return{
        id:r.id,
        nom,init,
        notas:notasCliente,
        tipo:r.tipo==='1a1'?'uno':'programa',
        actividad:parseFloat(r.actividad)||1.375,
        email:r.email||'',
        fechaNac:toDate(r.fecha_nacimiento),
        pesoIni,
        pesoAct,
        obj:r.objetivo_kg?Math.round(parseFloat(r.objetivo_kg)*10)/10:(objetivoKg?Math.round(objetivoKg*10)/10:Math.round(pesoIni*0.9*10)/10),
        altura:parseInt(r.altura)||175,
        semana:semanaActual,
        semTotal:parseInt(r.semanas_bloque)||13,
        nextRev,
        diasSemana:parseInt(r.dias_entreno)||4,
        pasosObj:parseInt(r.pasos_obj)||8000,
        equipamiento:r.lugar==='gym'?'Gimnasio completo':r.lugar||'Gimnasio completo',
        comidas:parseInt(r.comidas)||3,
        nivel:parseInt(r.nivel)||0,
        tiempoEnt:parseInt(r.tiempo_ent)||45,
        lesiones:r.lesiones||'',
        intolerancias:r.intolerancias||'',
        comentario:comentarioReal,
        medidasS0:medidasS0,
        entrenador:entrenadorAsignado,
        fase:r.fase||'deficit',
        objSemKg:r.obj_sem_kg!=null?parseFloat(r.obj_sem_kg):null,
        adh:parseFloat(r.adherencia)||0,
        checkInDone:false,
        revDone:false,
        diasSinPeso:0,
        macros:{kcal,p:prot,c:carbs,g:grasa},
        planPublicado:r.plan_publicado||r.visible_cliente||false,
        bloque:parseInt(r.numero_bloque)||1,
        bloqueHistorial:[],
        histPesos:[],
        checkIn:null,
        revision:null,
        inicioBloque:toDate(r.bloque_inicio||r.fecha_inicio),
        entrenador:'alvaro',
        nivel:parseInt(r.nivel)||1,
        rutina:r.rutina_cod||r.rutina_actual||'4D.TP',
        rutinaBase:rutinaDias,
        rutinaDias,
        rutinaSemanas,
        alimentos,
      };
    });

    // Replace C array — Gerard solo ve sus clientes asignados
    C.length=0;
    mapped.forEach(c=>{
      if(window.ENTRENADOR_ACTIVO==='gerard'){
        if(c.entrenador==='gerard')C.push(c);
      } else {
        C.push(c);
      }
    });

    // Load RUTINAS — only overrides, base loaded lazily by getRut
    mapped.forEach(c=>{
      if(!RUTINAS[c.id])RUTINAS[c.id]={__logs:{}};
      if(c.rutinaSemanas&&Object.keys(c.rutinaSemanas).length>0){
        Object.entries(c.rutinaSemanas).forEach(([sem,dias])=>{
          RUTINAS[c.id][parseInt(sem)]=JSON.parse(JSON.stringify(dias));
        });
      }
    });

    updateBadges();
    render();
    toast(`✅ ${mapped.length} clientes cargados desde BD`,'vd');
    console.log('[API] Clientes cargados:',mapped.length);
  }catch(e){
    console.error('[API] Error cargando clientes:',e.message,e);
    toast('Error cargando clientes: '+e.message,'rj');
  }
}
