// Toggle plan publicado via API
async function togglePublicarAPI(id){
  const c=byId(id);if(!c)return;
  c.planPublicado=!c.planPublicado;
  // Call API to update
  try{
    await apiCall('PATCH',`/api/clientes/${id}`,{plan_publicado:c.planPublicado});
  }catch(e){
    console.warn('[API] togglePublicar error:',e.message);
  }
  toast(c.planPublicado?'✅ Plan publicado':'Plan despublicado',c.planPublicado?'vd':'');
  render();
}

async function apiPublicarPlan(clienteId, bloqueId, publicado){
  try{
    if(publicado){
      await apiCall('POST',`/api/clientes/${clienteId}/aprobar-plan/${bloqueId}`);
    }
    toast(publicado?'Plan publicado al cliente ✅':'Plan despublicado','vd');
  }catch(e){
    toast('Error: '+e.message,'rj');
  }
}

async function apiGuardarPeso(clienteId, fecha, peso){
  try{
    await apiCall('POST','/api/entreno/peso',{fecha,peso});
  }catch(e){
    console.warn('[API] Error guardando peso:',e.message);
  }
}
