// ═══ CLIENT FULLSCREEN ═══
function openC(id,tab='resumen'){
  CLI_ID=id;CLI_TAB=tab;VIEW='client';try{localStorage.setItem('ef_cli',CLI_ID);}catch(e){}EDITING=false;
  RUT_CLI=id;
  ENT_VIEW='grid';
  // Update DIAS_BASE rest days based on client's rutinaDias
  const c=byId(id);
  if(c&&c.rutinaDias&&Object.keys(c.rutinaDias).length>0){
    const trainDays=Object.keys(c.rutinaDias).map(Number);
    DIAS_BASE.forEach((d,i)=>{
      d.rest=!trainDays.includes(i);
      if(!d.rest&&c.rutinaDias[String(i)]?.length>0){
        // Keep existing tipo or use generic
      }
    });
  }
  render();
}
function closeC(){VIEW='list';CLI_ID=null;render();}
function setTab(t){
  CLI_TAB=t;
  try{localStorage.setItem('ef_tab',t);localStorage.setItem('ef_cli',CLI_ID||'');}catch(e){}
  if(t!=='editar')EDITING=false;
  // Load revision data when opening revision tab
  if(t==='revision'&&CLI_ID&&API_TOKEN){
    const c=byId(CLI_ID);
    if(c){
      // Load pesos if needed
      if(!c.histPesos||!c.histPesos.length){
        apiCall('GET','/api/entreno/pesos/'+CLI_ID).then(rows=>{
          if(rows&&rows.length){
            c.histPesos=rows.map(r=>({f:new Date(r.fecha).toISOString().split('T')[0],v:parseFloat(r.peso)}));
            render();
          }
        }).catch(()=>{});
      }
      // Load revisiones (medidas + preguntas) if needed
      if(!c.revision&&!c._revLoaded){
        c._revLoaded=true;
        apiCall('GET','/api/entreno/revisiones/'+CLI_ID).then(rows=>{
          if(rows&&rows.length){
            const medidas={};const fotos=c.revision?.fotos||{};
            rows.forEach(r=>{
              const meds=typeof r.medidas==='string'?JSON.parse(r.medidas||'{}'):(r.medidas||{});
              Object.entries(meds).forEach(([nom,vals])=>{
                if(!medidas[nom])medidas[nom]={};
                if(typeof vals==='object'&&vals!==null)Object.assign(medidas[nom],vals);
                else if(vals!=null)medidas[nom]['S'+r.semana]=vals;
              });
            });
            c.revision={medidas,preguntas:{},fotos};render();
          }
        }).catch(()=>{});
      }
    }
  }
  render();
}

