// ═══ BIRTHDAY ═══
function checkBirthday(c){
  if(!c.fechaNac)return false;
  const t=new Date(),mm=String(t.getMonth()+1).padStart(2,'0'),dd=String(t.getDate()).padStart(2,'0');
  return c.fechaNac.slice(5)===mm+'-'+dd;
}
function cumpleBanner(){
  const hoy=C.filter(checkBirthday);
  if(!hoy.length)return'';
  return`<div class="cumple">
    <div style="font-size:26px">🎂</div>
    <div style="flex:1">
      <div style="font-weight:700;font-size:13.5px">¡Hoy cumple ${hoy.map(c=>c.nom.split(' ')[0]).join(' y ')}!</div>
      <div style="font-size:11.5px;opacity:.85;margin-top:2px">${hoy.map(c=>`${c.nom} · ${new Date().getFullYear()-parseInt(c.fechaNac.slice(0,4))} años · ${c.tipo==='uno'?'1:1':'Programa'}`).join(' · ')}</div>
    </div>
    <button onclick="this.closest('.cumple').remove()" style="background:rgba(255,255,255,.2);border:none;border-radius:50%;width:24px;height:24px;color:#fff;cursor:pointer;font-size:13px;flex-shrink:0">✕</button>
  </div>`;
}

// ═══ MINI CHART ═══
function miniChart(c){
  const vals=(c.histPesos||[]).map(p=>p.v);
  if(vals.length<2)return'<div style="text-align:center;color:var(--t3);font-size:12px;padding:8px">Sin datos de peso</div>';
  const W=520,H=72,PL=28,PR=10,PT=8,PB=16;
  const mn=Math.min(...vals,c.obj)-.5,mx=Math.max(...vals)+.5;
  const xOf=i=>PL+(i/(vals.length-1))*(W-PL-PR);
  const yOf=v=>PT+(1-(v-mn)/(mx-mn))*(H-PT-PB);
  const pts=vals.map((v,i)=>`${xOf(i).toFixed(1)},${yOf(v).toFixed(1)}`).join(' ');
  const oy=yOf(c.obj).toFixed(1);
  const area=`${xOf(0).toFixed(1)},${(H-PB).toFixed(1)} ${pts} ${xOf(vals.length-1).toFixed(1)},${(H-PB).toFixed(1)}`;
  return`<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px;overflow:visible">
    <defs><linearGradient id="cg" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#2E6DA4" stop-opacity=".18"/><stop offset="100%" stop-color="#2E6DA4" stop-opacity="0"/></linearGradient></defs>
    <line x1="${PL}" y1="${oy}" x2="${W-PR}" y2="${oy}" stroke="#0DBF6F" stroke-width="1.5" stroke-dasharray="5,3" opacity=".7"/>
    <polygon points="${area}" fill="url(#cg)"/>
    <polyline points="${pts}" fill="none" stroke="#2E6DA4" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>
    <circle cx="${xOf(vals.length-1).toFixed(1)}" cy="${yOf(vals[vals.length-1]).toFixed(1)}" r="4.5" fill="#2E6DA4" stroke="#fff" stroke-width="2"/>
    <text x="${PL}" y="${H}" font-size="9" fill="#9199AD">${vals[0]}kg</text>
    <text x="${W-PR}" y="${H}" text-anchor="end" font-size="9" fill="#2E6DA4" font-weight="700">${vals[vals.length-1]}kg</text>
    <text x="${W-PR}" y="${(parseFloat(oy)-4).toFixed(1)}" text-anchor="end" font-size="9" fill="#0DBF6F" font-weight="600">obj ${c.obj}kg</text>
  </svg>`;
}

// ═══ CHECK-INS ═══
function rCI(){
  const u=uno();
  const env=u.filter(c=>c.checkInDone),pend=u.filter(c=>!c.checkInDone);
  const adhM=u.length?Math.round(u.reduce((s,c)=>s+c.adh,0)/u.length*100):0;
  let h=cumpleBanner();
  h+=`<div class="kpig">
    <div class="kpi"><div class="kpi-ico" style="background:var(--vd2)">✅</div><div><div class="kpi-v" style="color:var(--vd)">${env.length}</div><div class="kpi-l">Enviados</div><div class="kpi-d" style="color:var(--t3)">de ${u.length}</div></div></div>
    <div class="kpi"><div class="kpi-ico" style="background:var(--am2)">⏳</div><div><div class="kpi-v" style="color:var(--am)">${pend.length}</div><div class="kpi-l">Pendientes</div></div></div>
    <div class="kpi"><div class="kpi-ico" style="background:#FEF9FF">⭐</div><div><div class="kpi-v" style="color:#9B59B6">${env.length?((env.reduce((s,c)=>s+(c.checkIn?.estrellas||0),0)/env.length).toFixed(1)):'—'}</div><div class="kpi-l">Bienestar medio</div></div></div>
    <div class="kpi"><div class="kpi-ico" style="background:var(--az3)">📊</div><div><div class="kpi-v" style="color:var(--az)">${adhM}%</div><div class="kpi-l">Adherencia media</div></div></div>
  </div>`;
  if(pend.length){
    h+=`<div class="card"><div class="ch"><h2>⏳ Pendientes (${pend.length})</h2></div>`;
    pend.forEach(c=>{h+=`<div class="arow am" onclick="openC('${c.id}','checkin')">
      <div class="av" style="background:${gc(ciIdx(c))};width:26px;height:26px">${c.init}</div>
      <div style="flex:1"><b>${c.nom}</b> <span style="color:var(--t3);font-size:11.5px">S${c.semana}/${c.semTotal}</span></div>
      <span style="font-size:12px;color:var(--az2);font-weight:600">Ver →</span>
    </div>`;});
    h+=`</div>`;
  }
  if(env.length){
    h+=`<div class="card"><div class="ch"><h2>✅ Recibidos (${env.length})</h2></div>
    <table class="tbl"><thead><tr><th>Cliente</th><th>Adh.</th><th>Entrenos</th><th>Nutrición</th><th>Pasos</th><th>⭐</th></tr></thead><tbody>`;
    env.forEach(c=>{const ci=c.checkIn||{};const ne=c.diasSemana||4;
      h+=`<tr onclick="openC('${c.id}','checkin')">
        <td><div style="display:flex;align-items:center;gap:8px"><div class="av" style="background:${gc(ciIdx(c))}">${c.init}</div>${c.nom}</div></td>
        <td><span class="badge ${adhBadge(c.adh)}">${Math.round(c.adh*100)}%</span></td>
        <td><b>${ci.entrenos||0}</b>/${ne}</td>
        <td>${ci.nutriDias?.length||0}/7</td>
        <td>${ci.pasosDias?.length||0}/7</td>
        <td>${'⭐'.repeat(ci.estrellas||0)}</td>
      </tr>`;});
    h+=`</tbody></table></div>`;
  }
  return h;
}

// ═══ REVISIONES ═══
function rRevs(tipo){
  const clis=tipo==='uno'?uno():prog();
  const conRev=clis.filter(c=>c.semana===c.nextRev);
  const env=conRev.filter(c=>c.revDone),pend=conRev.filter(c=>!c.revDone);
  const prox=clis.filter(c=>c.nextRev-c.semana===1);
  const lbl=tipo==='uno'?'1:1':'Programa';
  let h=`<div class="kpig">
    <div class="kpi"><div class="kpi-ico" style="background:var(--rj2)">📋</div><div><div class="kpi-v" style="color:var(--rj)">${conRev.length}</div><div class="kpi-l">Esta semana — ${lbl}</div></div></div>
    <div class="kpi"><div class="kpi-ico" style="background:var(--vd2)">✅</div><div><div class="kpi-v" style="color:var(--vd)">${env.length}</div><div class="kpi-l">Recibidas</div></div></div>
    <div class="kpi"><div class="kpi-ico" style="background:var(--am2)">⏳</div><div><div class="kpi-v" style="color:var(--am)">${pend.length}</div><div class="kpi-l">Pendientes</div></div></div>
    <div class="kpi"><div class="kpi-ico" style="background:var(--az3)">📅</div><div><div class="kpi-v" style="color:var(--az2)">${prox.length}</div><div class="kpi-l">Próx. semana</div></div></div>
  </div>`;
  if(env.length){
    h+=`<div class="card"><div class="ch"><h2>✅ Dar feedback</h2></div>`;
    env.forEach(c=>{h+=`<div style="display:flex;align-items:center;gap:11px;padding:11px 14px;border-bottom:1px solid var(--bor2);cursor:pointer" onclick="openC('${c.id}','revision')">
      <div class="av" style="background:${gc(ciIdx(c))}">${c.init}</div>
      <div style="flex:1"><div style="font-weight:700">${c.nom}</div><div style="font-size:11.5px;color:var(--t3)">S${c.nextRev}/${c.semTotal}</div></div>
      <span class="badge bvd">Enviada</span><span style="font-size:12px;color:var(--az2);font-weight:700;margin-left:8px">Feedback →</span>
    </div>`;});
    h+=`</div>`;
  }
  if(pend.length){
    h+=`<div class="card"><div class="ch"><h2>⏳ Pendientes de enviar</h2></div>`;
    pend.forEach(c=>{h+=`<div class="arow am" onclick="openC('${c.id}','resumen')">
      <div class="dot dam"></div><div style="flex:1"><b>${c.nom}</b> <span style="color:var(--t3);font-size:11.5px">S${c.nextRev} esta semana</span></div>
      <span style="font-size:12px;color:var(--az2)">Ver →</span>
    </div>`;});
    h+=`</div>`;
  }
  if(prox.length){
    h+=`<div class="card"><div class="ch"><h2>📅 La semana que viene</h2></div><div class="cb" style="display:flex;flex-wrap:wrap;gap:6px">`;
    prox.forEach(c=>{h+=`<div class="badge baz" style="cursor:pointer" onclick="openC('${c.id}','resumen')">${c.nom.split(' ')[0]} · S${c.nextRev}</div>`;});
    h+=`</div></div>`;
  }
  return h;
}

// ═══ ALERTAS (sin lesiones, por tipo) ═══
function rAlertas(tipo){
  const clis=tipo==='uno'?uno():prog();
  const lbl=tipo==='uno'?'1:1':'Programa';
  const sinPeso=clis.filter(c=>c.diasSinPeso>7).sort((a,b)=>b.diasSinPeso-a.diasSinPeso);
  const bajAdh=clis.filter(c=>c.adh<0.6);
  const rowFn=(c,txt)=>`<div class="arow rj" onclick="openC('${c.id}','resumen')">
    <div class="av" style="background:${gc(ciIdx(c))};width:26px;height:26px">${c.init}</div>
    <div style="flex:1"><b>${c.nom}</b> <span style="color:var(--t3);font-size:11.5px">${txt}</span></div>
    <span style="font-size:12px;color:var(--az2);font-weight:600">Ver →</span>
  </div>`;
  const empty=`<div style="padding:14px;font-size:13px;color:var(--t3)">✅ Sin alertas</div>`;
  return`
  <div class="card"><div class="ch" style="background:var(--rj2)"><h2 style="color:var(--rj)">⚠️ Sin pesar +7 días — ${lbl}</h2></div>
    ${sinPeso.length?sinPeso.map(c=>rowFn(c,`— ${c.diasSinPeso} días sin registrar peso`)).join(''):empty}
  </div>
  <div class="card"><div class="ch" style="background:var(--rj2)"><h2 style="color:var(--rj)">📉 Adherencia &lt;60% — ${lbl}</h2></div>
    ${bajAdh.length?bajAdh.map(c=>rowFn(c,`— ${Math.round(c.adh*100)}%`)).join(''):empty}
  </div>`;
}

// ═══ LISTA CLIENTES ═══
function rLista(tipo){
  let clis=tipo==='uno'?uno():prog();
  if(SEARCH)clis=clis.filter(c=>c.nom.toLowerCase().includes(SEARCH)||c.lesiones?.toLowerCase().includes(SEARCH));
  if(!clis.length)return`<div class="card"><div class="cb" style="text-align:center;color:var(--t3);padding:30px">${SEARCH?`Sin resultados para "${SEARCH}"`:'Sin clientes'}</div></div>`;
  return`<div class="card">
  <table class="tbl"><thead><tr>
    <th>Cliente</th><th>Semana</th><th>Adherencia</th><th>Peso act.</th>
    <th>Objetivo</th><th>Próx. rev.</th>${tipo==='uno'?'<th>Check-in</th>':''}<th>Plan</th>
  </tr></thead><tbody>
  ${clis.map(c=>{const ri=c.nextRev-c.semana;return`<tr onclick="openC('${c.id}','resumen')">
    <td><div style="display:flex;align-items:center;gap:8px">
      <div class="av" style="background:${gc(ciIdx(c))}">${c.init}</div>
      <div>
        <div style="font-weight:600">${c.nom}</div>
        ${c.lesiones?`<div style="font-size:10.5px;color:var(--am)">🩹 ${c.lesiones.split(',')[0].trim()}</div>`:''}
      </div>
    </div></td>
    <td><span class="badge baz">S${c.semana}/${c.semTotal}</span></td>
    <td><div style="display:flex;align-items:center;gap:6px">
      <div class="dot ${adhDot(c.adh)}"></div>
      <span style="font-weight:700;color:${adhCol(c.adh)}">${Math.round(c.adh*100)}%</span>
    </div></td>
    <td style="font-weight:700;color:var(--az2)">${c.pesoAct}kg</td>
    <td style="color:var(--t3)">${c.obj}kg</td>
    <td><span class="badge ${ri===0?'brj':ri===1?'bam':'bgr'}">${ri===0?'⚠️ Esta sem':ri===1?'Próx.':'S'+c.nextRev}</span></td>
    ${tipo==='uno'?`<td><span class="badge ${c.checkInDone?'bvd':'bam'}">${c.checkInDone?'✅':'⏳'}</span></td>`:''}
    <td><span class="badge ${c.planPublicado?'bvd':'bgr'}">${c.planPublicado?'Publicado':'Borrador'}</span></td>
  </tr>`;}).join('')}
  </tbody></table></div>`;
}


async function abrirAppCliente(clienteId){
  try{
    const data=await apiCall('GET','/api/clientes/'+clienteId+'/token-preview');
    const url='https://enformafit.github.io/enformafit-app/?tk='+encodeURIComponent(data.token);
    window.open(url,'_blank');
  }catch(e){
    toast('Error abriendo app: '+e.message,'rj');
  }
}


